   const pool=gatherPool(g,profession),random=options.random||Math.random,ids=[];
   for(let i=0;i<2;i++){
    let roll;try{roll=Number(random())}catch(_){return {error:'Could not select Gather materials.'}}
    if(!Number.isFinite(roll)||roll<0||roll>=1)return {error:'Could not select Gather materials.'};
    ids.push(pool[Math.floor(roll*pool.length)]);
   }
