  // an ownership clause must not be bypassed by the old prefix-only regular expression.
  if(/^Own LT\d+(?: [^;]*?)?$/i.test(u)){
   const ids=u.match(/LT\d+/g)||[];return ids.length&&ids.every(id=>ownsPartyLoot(g,id))?null:u;
  }
  let m=u.match(/^Possess (LT\d+)$/i);if(m)return ownsPartyLoot(g,m[1])?null:u;
  m=u.match(/^Complete (Q\d+)$/i);if(m)return c.questStatus?.[m[1]]==='Completed'?null:u;
  m=u.match(/^(Q\d+) active$/i);if(m)return c.currentQuest===m[1]&&!c.downtime?null:u;
  m=u.match(/^(Q\d+) active or completed$/i);if(m)return (c.currentQuest===m[1]&&!c.downtime)||c.questStatus?.[m[1]]==='Completed'?null:u;
  if(/^Q001 active or Stonebrook upgrade phase$/i.test(u)||/^Stonebrook upgrade phase$/i.test(u))return null;
  if(/^Complete Q003 or restore Fallen Watchtower$/i.test(u))return c.questStatus?.Q003==='Completed'||Object.values(g.tiles||{}).some(t=>String(t.name).toLowerCase()==='fallen watchtower')?null:u;
  m=u.match(/^(Goblin War Camp|Goblin Mines|Ritual Circle|Ancient Portal|Ancient Crypt) revealed$/i);if(m)return Object.values(g.tiles||{}).some(t=>String(t.name).toLowerCase()===m[1].toLowerCase())?null:u;
  if(/^Defeat at least 3 Goblins$/i.test(u))return Number(c.goblinDefeatCount||0)>=3?null:u;
  m=u.match(/^Defeat (?:a |an |the )(.+)$/i);if(m)return (c.defeatedEnemyNames||[]).some(name=>String(name).toLowerCase().includes(m[1].toLowerCase()))?null:u;
  if(/^Complete all Main Quests$/i.test(u))return ['Q001','Q002','Q004','Q005','Q007','Q008','Q010','Q011','Q012'].every(id=>c.questStatus?.[id]==='Completed')?null:u;
